static int g_is_initialized;
static int g_help_width;

/**
 * menu_lower -- ASCII lower-case of one character.
 * Works by offsetting 'A'..'Z'; every other value is returned unchanged.
 * Input: c character. Returns: the lower-case character. No side effects.
 */
static char menu_lower(char c)
{
    return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
}

/**
 * menu_streq_nocase -- case-insensitive string equality (exact length, no prefixes).
 * Walks both strings together and stops at the first difference or terminator.
 * Input: a, b NUL-terminated strings, both non-NULL. Returns: 1 when equal, else 0.
 */
static int menu_streq_nocase(const char *a, const char *b)
{
    while (*a != '\0' && *b != '\0') {
        if (menu_lower(*a) != menu_lower(*b)) {
            return 0;
        }
        a++;
        b++;
    }
    return (*a == '\0' && *b == '\0') ? 1 : 0;
}

/**
 * menu_strlen -- length of a NUL-terminated string (no libc dependency).
 * Input: s non-NULL string. Returns: the number of characters before the NUL.
 */
static int menu_strlen(const char *s)
{
    int n = 0;

    while (s[n] != '\0') {
        n++;
    }
    return n;
}

/**
 * menu_write_pad -- write a string followed by spaces up to a column width.
 * Used by the help output so every " - " separator lands in one column.
 * Input: text string, width column width. Side effect: output through menu_write.
 */
static void menu_write_pad(const char *text, int width)
{
    char sp[2] = { ' ', '\0' };
    int  n = menu_strlen(text);

    menu_write(text);
    while (n < width) {
        menu_write(sp);
        n++;
    }
}

/**
 * Menu_Init -- prepare the runtime state of the menu.
 * The command metadata is generated as constant tables, so only the help column width
 * is computed: the longest syntax string over all commands and the built-ins.
 * Side effects: sets g_is_initialized and g_help_width; idempotent.
 */
void Menu_Init(void)
{
    int i;
    int w = 6; /* "HELP" / "?" / "EXIT" entries: the widest built-in label */

    for (i = 0; i < MENU_COMMAND_COUNT; i++) {
        const int n = menu_strlen(g_commands[i].syntax);

        if (n > w) {
            w = n;
        }
    }
    g_help_width = w;
    g_is_initialized = 1;
}

/**
 * Menu_PrintHelp -- print every command, then the built-ins, one aligned line each.
 * Lines are "  <syntax padded to the widest syntax> - <description>".
 * Side effects: output through menu_write; calls Menu_Init when needed.
 */
void Menu_PrintHelp(void)
{
    int i;

    if (!g_is_initialized) {
        Menu_Init();
    }
    for (i = 0; i < MENU_COMMAND_COUNT; i++) {
        menu_write("  ");
        menu_write_pad(g_commands[i].syntax, g_help_width);
        menu_write(" - ");
        menu_write(g_commands[i].description);
        menu_write("\n");
    }
    menu_write("  ");
    menu_write_pad("HELP", g_help_width);
    menu_write(" - Show this list\n  ");
    menu_write_pad("?", g_help_width);
    menu_write(" - Show this list\n  ");
    menu_write_pad("EXIT", g_help_width);
    menu_write(" - Leave the CLI and return to the C64 screen\n");
}

/**
 * Menu_ParseU32 -- parse a decimal or 0x-prefixed hexadecimal number.
 * Accepts only digits (no sign, no spaces) and rejects overflow past 32 bits.
 * Input: text NUL-terminated, value result (written only on success).
 * Returns: 1 on success, 0 on a malformed or out-of-range number.
 */
int Menu_ParseU32(const char *text, unsigned long *value)
{
    unsigned long acc = 0u;
    unsigned long base = 10u;
    int digits = 0;

    if (text == NULL || value == NULL) {
        return 0;
    }
    if (text[0] == '0' && (text[1] == 'x' || text[1] == 'X')) {
        base = 16u;
        text += 2;
    }
    for (; *text != '\0'; text++) {
        unsigned long d;
        const char c = menu_lower(*text);

        if (c >= '0' && c <= '9') {
            d = (unsigned long)(c - '0');
        } else if (base == 16u && c >= 'a' && c <= 'f') {
            d = (unsigned long)(c - 'a') + 10u;
        } else {
            return 0;
        }
        if (acc > (0xFFFFFFFFul - d) / base) {
            return 0;
        }
        acc = acc * base + d;
        digits++;
    }
    if (digits == 0) {
        return 0;
    }
    *value = acc;
    return 1;
}

/**
 * menu_tokenize -- split a line in place at spaces and tabs.
 * Writes NULs into buf and stores one pointer per token.
 * Input: buf modifiable line, tokens output array, max its capacity.
 * Returns: the token count, or -1 when there are more than max tokens.
 */
static int menu_tokenize(char *buf, const char **tokens, int max)
{
    int n = 0;

    while (*buf != '\0') {
        while (*buf == ' ' || *buf == '\t') {
            *buf++ = '\0';
        }
        if (*buf == '\0') {
            break;
        }
        if (n >= max) {
            return -1;
        }
        tokens[n++] = buf;
        while (*buf != '\0' && *buf != ' ' && *buf != '\t') {
            buf++;
        }
    }
    return n;
}

/**
 * menu_match_and_dispatch -- match one command definition and run its callback.
 * Sets *matched = 1 only after the token count is in [min_tokens, max_tokens], every
 * keyword equals the input token at its position (case-insensitive), and the callback
 * pointer is valid. Parameters are captured into the callback context in order.
 * Input: def, parsed the command, tokens/count the input line, matched output flag.
 * Returns: the callback's return value when matched, otherwise -1 (never inferred as a
 * match: the caller must test *matched).
 */
static int menu_match_and_dispatch(const MenuCommandDef *def, const ParsedCommand *parsed,
                                   const char **tokens, int count, int *matched)
{
    MenuCommandContext ctx;
    int i;

    *matched = 0;
    if (!parsed->valid || count < parsed->min_tokens || count > parsed->max_tokens) {
        return -1;
    }
    ctx.argc = 0;
    for (i = 0; i < MENU_MAX_ARGS; i++) {
        ctx.argv[i] = NULL;
    }
    for (i = 0; i < parsed->token_count && i < count; i++) {
        if (parsed->tokens[i].type == MENU_TOKEN_KEYWORD) {
            if (!menu_streq_nocase(parsed->tokens[i].text, tokens[i])) {
                return -1;
            }
        } else if (ctx.argc < MENU_MAX_ARGS) {
            ctx.argv[ctx.argc++] = tokens[i];
        }
    }
    if (def->callback == NULL) {
        return -1;
    }
    *matched = 1;
    return def->callback(&ctx);
}

/**
 * Menu_ProcessLine -- parse one input line and dispatch it.
 * Copies the line to a stack buffer, tokenizes it, handles HELP / ? / EXIT, then offers
 * the tokens to every command until one reports matched == 1. An empty line does nothing.
 * Input: line NUL-terminated text without the line ending.
 * Returns: the callback's return value, 0 for an empty line or help, MENU_EXIT for EXIT,
 * -1 for NULL, an over-long line, an unknown command or bad arguments (a message is printed).
 */
int Menu_ProcessLine(const char *line)
{
    char buf[MENU_LINE_MAX];
    const char *tokens[MENU_MAX_TOKENS];
    int i;
    int count;
    int partial = 0;

    if (line == NULL) {
        return -1;
    }
    if (!g_is_initialized) {
        Menu_Init();
    }
    if (menu_strlen(line) >= MENU_LINE_MAX) {
        menu_write("Line too long\n");
        return -1;
    }
    for (i = 0; (buf[i] = line[i]) != '\0'; i++) {
    }
    count = menu_tokenize(buf, tokens, MENU_MAX_TOKENS);
    if (count == 0) {
        return 0;
    }
    if (count < 0) {
        menu_write("Unknown command, HELP lists the commands\n");
        return -1;
    }
    if (count == 1 && (menu_streq_nocase(tokens[0], "HELP") || menu_streq_nocase(tokens[0], "?"))) {
        Menu_PrintHelp();
        return 0;
    }
    if (count == 1 && menu_streq_nocase(tokens[0], "EXIT")) {
        return MENU_EXIT;
    }
    for (i = 0; i < MENU_COMMAND_COUNT; i++) {
        int matched = 0;
        const int rc = menu_match_and_dispatch(&g_commands[i], &g_parsed_commands[i], tokens, count, &matched);

        if (matched) {
            return rc;
        }
        if (menu_streq_nocase(g_parsed_commands[i].tokens[0].text, tokens[0])) {
            partial = 1;
        }
    }
    menu_write(partial ? "Bad arguments, HELP shows the syntax\n" : "Unknown command, HELP lists the commands\n");
    return -1;
}
